/** AUD-V2 — declarative source of the Little World audio catalogue. `tools/generate-audio.mjs`
 * turns it into `public/audio/catalog.json` (runtime), `assets/audio/production-manifest.json`
 * (machine-readable brief for the audio generation agent) and `docs/38-AUDIO-V2-INVENTAIRE.md`.
 * One *event* may use several *resources*; several events may share resources (reuse). Only the
 * existing V1 library and procedural descriptors are available; everything else is PLANNED. */
import type {AmbienceProfile,AudioAssetV2,AudioDefinitionV2,EventCategory,MusicCue,ProceduralSpec,SoundEventV2,SoundVariantV2} from './catalog.ts';
