export const CATALOG_VERSION='2.0.0-aud-v2';
type Wave=1|2|3;
/** A group = takes sharing one condition. `reuse` points to another group's files (no new file). */
export interface TakeGroup {key:string;when?:SoundCondition;also?:SoundCondition[];takes?:number;later?:number;wave?:Wave;seconds?:[number,number];loop?:boolean;channels?:1|2;brief?:string;reuse?:string;gain?:number;pitch?:number;library?:string[];procedural?:ProceduralSpec;}
export interface EventSpec {id:string;category:EventCategory;description:string;trigger:string;context:string[];spatial:'joueur'|'monde'|'non'|'boucle globale';kind:'sample'|'procedural';groups:TakeGroup[];fallback?:string;params?:Partial<SoundEventV2>;emitted:boolean;note?:string;}
